#!/usr/bin/env python3
"""Generate the opt-in five-lane amd64 expansion and its hash wrapper."""
from pathlib import Path

root = Path(__file__).parent
header = '''// Copyright 2010 The Go Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.
//
// Code generated by five_generate.py; DO NOT EDIT.
//go:build amd64 && !purego
'''
# Ten chaining words, one state pointer and two temporaries occupy the available
# registers. R14 (g) and BP are preserved. Only the output offset is on the stack.
pairs = [('R8', 'R9'), ('R10', 'R11'), ('R12', 'R13'), ('AX', 'BX'), ('CX', 'DX')]
out = [header, '#include "textflag.h"', '#include "go_asm.h"',
       'TEXT ·expandFiveAsm(SB), NOSPLIT, $8-16',
       'MOVQ c+0(FP), R15', 'MOVQ words+8(FP), DI', 'XORQ SI, SI', 'keyFive:']
for k in range(5):
    out += [f'MOVL {k*72}(DI)(SI*4), AX', f'XORL AX, {k*4168}(R15)(SI*4)']
out += ['INCQ SI', 'CMPQ SI, $18', 'JNE keyFive', 'MOVQ $0, offset-8(SP)']
for left, right in pairs:
    out += [f'XORL {left}, {left}', f'XORL {right}, {right}']
out += ['blockFive:']
for k, (left, _) in enumerate(pairs):
    out += [f'XORL state_p+{k*4168}(R15), {left}']
for round in range(1, 17):
    for k, (left, right) in enumerate(pairs):
        source, target = (left, right) if round % 2 else (right, left)
        for field, shift, operation in [('s0', 24, 'MOVL'), ('s1', 16, 'ADDL'), ('s2', 8, 'XORL'), ('s3', 0, 'ADDL')]:
            if shift:
                out += [f'MOVL {source}, SI', f'SHRL ${shift}, SI']
                if shift != 24:
                    out += ['MOVBLZX SI, SI']
            else:
                out += [f'MOVBLZX {source}, SI']
            out += [f'{operation} state_{field}+{k*4168}(R15)(SI*4), DI']
        out += [f'XORL state_p+{k*4168+round*4}(R15), {target}', f'XORL DI, {target}']
out += ['MOVQ offset-8(SP), DI']
for k, (left, right) in enumerate(pairs):
    out += [f'XORL state_p+{k*4168+68}(R15), {right}', f'XCHGL {left}, {right}',
            f'MOVL {left}, {k*4168}(R15)(DI*1)', f'MOVL {right}, {k*4168+4}(R15)(DI*1)']
out += ['ADDQ $8, DI', 'MOVQ DI, offset-8(SP)', 'CMPQ DI, $state__size', 'JNE blockFive', 'RET']
(root / 'five_amd64.s').write_text('\n'.join(out) + '\n')

# Keep validation, salted expansion, cost rounds and final encryption identical
# to Sum5. Replace only the repeated unsalted expansion calls.
source = (root / 'lanes_generated.go').read_text()
start = source.index('func Sum5(')
opening = source.index('{', start)
depth, end = 1, opening + 1
while depth:
    depth += (source[end] == '{') - (source[end] == '}')
    end += 1
wrapper = source[start:end].replace('func Sum5(', 'func Five(').replace('expand5(&st,', 'expandFiveAsm(&st,')
(root / 'five_amd64.go').write_text(header + '''
package bcryptlane

import "encoding/binary"

//go:noescape
func expandFiveAsm(c *[5]state, words *[5][18]uint32)

// Five computes the same independent checksums as Sum5 using amd64 expansion.
''' + wrapper + '\n')
